(* Examples of how to use the library or apply the theorems: *)
(* 1. To create a simple predicate formula: `Pred 1 [2; 3]`. *)
(* 2. To create a conjunction of two equality formulas: `And (Eq 1 2) (Eq 3 4)`. *)
(* 3. To create a universal quantification formula: `Forall 1 (Eq 1 2)`. *)
(* 4. To apply a theorem, refer to `Theorem_1` in `Part_V`. *)
(* - `Pred` represents a predicate with a natural number identifier and a list of natural number arguments. This is used to create predicate formulas in the logical system. *)
(* - `Eq` represents an equality between two natural numbers. This is used to create equality formulas in the logical system. *)
(* - `And`, `Or`, `Imp` represent logical connectives for conjunction, disjunction, and implication, respectively. These are used to create logical connective formulas in the logical system. *)
(* - `Not` represents a logical negation. This is used to create negation formulas in the logical system. *)
(* - `Forall` and `Exists` represent universal and existential quantification over a natural number variable, respectively. These are used to create quantification formulas in the logical system. *)
Inductive Fo : Type :=
(* `Pred` represents a predicate with a natural number identifier and a list of natural number arguments. *)
| Pred (n:nat) (args:list nat)
(* `Eq` represents an equality between two natural numbers. *)
| Eq (t1 t2:nat)
(* `And` represents a logical conjunction of two formulas. *)
| And (f1 f2:Fo)
(* `Or` represents a logical disjunction of two formulas. *)
| Or (f1 f2:Fo)
(* `Imp` represents a logical implication between two formulas. *)
| Imp (f1 f2:Fo)
(* `Not` represents a logical negation of a formula. *)
| Not (f:Fo)
(* `Forall` represents a universal quantification over a natural number variable in a formula. *)
| Forall (x:nat) (f:Fo)
(* `Exists` represents an existential quantification over a natural number variable in a formula. *)
| Exists (x:nat) (f:Fo). 
| Pred (n:nat) (args:list nat)
| Eq (t1 t2:nat)
| And (f1 f2:Fo)
| Or (f1 f2:Fo)
| Imp (f1 f2:Fo)
| Not (f:Fo)
| Forall (x:nat) (f:Fo)
| Exists (x:nat) (f:Fo).

